def dinic(s, t):
    flow = 0
    while bfs(s, t):
        ptr = [0]*n
        while True:
            pushed = dfs(s, t, INF, ptr)
            if not pushed: break
            flow += pushed
    return flow

def orient(a, b, c):
    v = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x)
    return 1 if v > 0 else (-1 if v < 0 else 0)

def cross(o, a, b):
    return (a[0]-o[0])*(b[1]-o[1]) - (a[1]-o[1])*(b[0]-o[0])

def hull(points):
    pts = sorted(points)
    lo = []
    for p in pts:
        while len(lo) >= 2 and cross(lo[-2], lo[-1], p) <= 0:
            lo.pop()
        lo.append(p)
    return lo

def closest(points):
    if len(points) <= 3:
        return brute_force(points)
    mid = len(points) // 2
    d = min(closest(points[:mid]), closest(points[mid:]))
    strip = [p for p in points if abs(p[0] - points[mid][0]) < d]
    return min(d, check_strip(strip, d))

def z_function(s):
    n = len(s); z = [0]*n; l = r = 0
    for i in range(1, n):
        if i <= r: z[i] = min(r - i + 1, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]: z[i] += 1
        if i + z[i] - 1 > r: l, r = i, i + z[i] - 1
    return z

def search(text, pat):
    pi = prefix_function(pat)
    j = 0; res = []
    for i, c in enumerate(text):
        while j and c != pat[j]: j = pi[j-1]
        if c == pat[j]: j += 1
        if j == len(pat):
            res.append(i - len(pat) + 1)
            j = pi[j-1]
    return res

def rabin_karp(text, pat):
    m = len(pat); hp = hash(pat)
    hw = hash(text[:m]); res = []
    for i in range(len(text) - m + 1):
        if hw == hp and text[i:i+m] == pat:
            res.append(i)
        if i + m < len(text):
            hw = slide(hw, text[i], text[i+m], B, M, P)
    return res

def build_prefix(s, base, mod):
    n = len(s); h = [0]*(n+1); pw = [1]*(n+1)
    for i, c in enumerate(s):
        h[i+1] = (h[i]*base + ord(c)) % mod
        pw[i+1] = (pw[i]*base) % mod
    return h, pw

